$('request').onsubmit=async e=>{
 e.preventDefault();const form=$('request'),b=form.querySelector('button[type=submit],button:not([type])');if(!b||!form.reportValidity())return;if(checkoutBusy||cartKey){status(pendingMessage,true);return;}
 if(b.disabled)return;b.disabled=true;form.setAttribute('aria-busy','true');checkoutBusy=true;let sent=false,retry=Boolean(requestKey);
 try{
  let payload={service_id:$('service').value,quantity:Number($('quantity').value)};
  const signature=JSON.stringify(payload);
  if(requestKey&&requestKey.signature!==signature){
   const previous=JSON.parse(requestKey.signature);
   if(!confirm('Pesanan sebelumnya belum pasti: '+(catalogById.get(previous.service_id)?.name||previous.service_id)+' × '+previous.quantity+'. Ulangi pesanan sebelumnya dengan ID yang sama?'))throw Error(pendingMessage);
   payload=previous;
  }
  requestKey??={signature:JSON.stringify(payload),id:crypto.randomUUID()};
  saveCheckoutDraft();sent=true;const {order,checkout_pricing}=validateCheckoutReceipt(await api('orders',{...payload,request_id:requestKey.id}),[payload],{single:true});
  requestKey=null;persistDraft();await load();status('Permintaan tercatat: '+order.id+checkoutPricingPreview(checkout_pricing));
 }catch(e){if(shouldClearPendingCheckout({sent,retry,error:e})){requestKey=null;persistDraft();}status(e.message+(requestKey?' '+pendingMessage:''),true);}
 finally{checkoutBusy=false;form.removeAttribute('aria-busy');b.disabled=false;}
};
